create temp table r48ops_done on commit drop as select distinct e.user_id from academy_enrollments e where app.academy_done(e.user_id);
insert into academy_sections (slug, title, blurb, guide_refs) values ('r48-ops-screens', 'The calendar, check-outs and one portal', 'Find a car on a long calendar, the two jobs at the end of a trip, your roles in one portal, and where Unfinished rentals lives.', array['admin/calendars', 'va/shared-tools', 'admin/getting-around-admin', 'va/add-a-rental-by-hand']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-ops-screens'), 1, 'Find a car on the calendar', '[{"caption":"A long list, cut down","say":"With a hundred cars the calendar is a long list. Search takes a car, a plate, a booking number or a surname. Under it you filter by car status, class, owner and availability.","visual":{"kind":"list","heading":"Filters","items":["Car status","Class","Owned by","Availability: available now, free today, free every day shown"]}},{"caption":"Groups that fold","say":"Group by class, owner, car status or availability. Each heading says how many cars it holds and how many are free today. Press a heading to fold its cars away.","visual":{"kind":"steps","heading":"Group by","items":["Choose Group by","Read the count on each heading","Press a heading to fold it"]}},{"caption":"Know what you are looking at","say":"A filter that is on has a black edge, and the count on the right says how many cars show out of all of them. If a car seems missing, press Clear first.","visual":{"kind":"rule","heading":"A car seems missing?","text":"Look at the count, then press Clear to take the filters off.","tone":"info"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-ops-screens'), 2, 'A return is a check-out', '[{"caption":"The words","say":"A pickup is the check-in. A return is the check-out. We never call a return a check-in, on the calendar, in the field portal or to a renter.","visual":{"kind":"title","heading":"Pickup: check-in. Return: check-out.","text":"The same words everywhere"}},{"caption":"Two jobs at the end of a trip","say":"Under the bars each trip that ends has two chips, each its own job. Check-out, with its time. And Cleaning, the post-trip cleaning, with its window.","visual":{"kind":"list","heading":"The end of a trip","items":["Check-out, with its time","Cleaning, the post-trip cleaning","A tick means done"]}},{"caption":"The time it really came back","say":"Before the return the check-out chip shows when the car is due. Once the car is back it shows the time it actually came back, and the booking''s panel shows both.","visual":{"kind":"rule","heading":"Actual return time","text":"Due before the return; the real time once the car is back.","tone":"ok"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-ops-screens'), 3, 'One portal, your roles', '[{"caption":"No more choosing a portal","say":"If your account has more than one role, Sales and Field work, or you also own a car with us, signing in opens the role you used last. There is no Choose a portal stop.","visual":{"kind":"title","heading":"One portal","text":"Every role of your account in one place"}},{"caption":"Working as","say":"Working as, at the top of every page, lists every role you have. The one you are in is black. Under it, Pages of your other roles goes straight to a page of another role.","visual":{"kind":"steps","heading":"Switch","items":["Look at Working as","Press the role you want","Or open Pages of your other roles"]}},{"caption":"Access is the same","say":"Nothing about what you may open changed. Each page still checks your role. And Unfinished rentals now lives where a sale is chased to its end: Today and Bookings, for Sales and Admins. The forms show only your own unfinished ones.","visual":{"kind":"rule","heading":"Permissions","text":"Exactly as before: the switcher only shows the roles you have.","tone":"info"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-ops-screens'), 1, 'A renter brings the car back. What is that called?', '["A check-in", "A check-out", "A handover", "A pickup"]'::jsonb, 1, 'A pickup is the check-in; a return is the check-out.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-ops-screens'), 2, 'Which two jobs does the calendar show at the end of a trip?', '["Return check-out and post-trip cleaning", "Pickup and delivery", "Photo shoot and tracker install", "Only one job called Return"]'::jsonb, 0, 'The return check-out (with its time) and the post-trip cleaning are two separate jobs.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-ops-screens'), 3, 'The car came back 90 minutes late. What time does its Check-out chip show?', '["The time it was due", "The time it actually came back", "No time", "The pickup time"]'::jsonb, 1, 'Once the car is back the chip shows the actual return time; the booking panel shows the due time beside it.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-ops-screens'), 4, 'The calendar shows 12 of 140 cars and one you need seems missing. What first?', '["Report a bug", "Look at the count and press Clear", "Add the car again", "Ask the owner"]'::jsonb, 1, 'A filter is on: the count says how many cars show, and Clear takes the filters off.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-ops-screens'), 5, 'You work in Sales and Field work. How do you get to your field jobs?', '["Sign out and sign in again", "Choose a portal after signing in", "Press Field work under Working as", "Ask an Admin"]'::jsonb, 2, 'Working as lists every role of your account at the top of every page.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-ops-screens'), 6, 'Where does everyones list of Unfinished rentals show?', '["On every staff page", "On Today and Bookings, for Sales and Admins", "Only in Settings", "On the calendar"]'::jsonb, 1, 'It lives on Today and Bookings for Sales and Admins; the forms show only your own unfinished ones.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
